.checkbox-row input[type="checkbox"][aria-invalid="true"]:focus-visible {
  outline-color: var(--error);
  box-shadow: 0 0 0 5px rgba(255, 107, 107, 0.2);
}

/* ── Label ─────────────────────────────────────────────────────── */
.checkbox-row label {
  font-size: 0.9375rem;
  cursor: pointer;
  color: var(--text-primary);
