.checkbox-row label a {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.checkbox-row label a:hover { color: var(--accent-hover); }
.checkbox-row label a:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
  border-radius: 2px;
}

.required-mark {
  color: var(--error);
  margin-left: 2px;
}

/* ── Help & error text ─────────────────────────────────────────── */
.help-text {
  font-size: 0.8125rem;
  color: var(--text-muted);
  padding-left: 2rem; /* align under label, past checkbox */
}

.error-text {
  font-size: 0.8125rem;
  color: var(--error);
  padding-left: 2rem;
  display: flex;
  align-items: flex-start;
  gap: 0.25rem;
}

.error-text[hidden] { display: none; }

/* Error field highlight */
.form-field:has([aria-invalid="true"]) {
  background: var(--error-bg);
  border-radius: 6px;
  padding: 0.75rem;
}

/* ── Required legend ───────────────────────────────────────────── */
.required-legend {
  font-size: 0.8125rem;
  color: var(--text-muted);
}
.required-legend span { color: var(--error); }

/* ── Submit button ─────────────────────────────────────────────── */
button[type="submit"] {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  padding: 0.8rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  width: 100%;
}
