 (function () {
   "use strict";

   const form       = document.getElementById("consent-form");
   const checkbox   = document.getElementById("agree-terms");
   const errorMsg   = document.getElementById("agree-error");
   const statusMsg  = document.getElementById("status-message");

   function setInvalid() {
     checkbox.setAttribute("aria-invalid", "true");
     errorMsg.hidden = false;
   }

   function setValid() {
     checkbox.setAttribute("aria-invalid", "false");
     errorMsg.hidden = true;
   }

   /* Clear error as soon as the user checks the box */
   checkbox.addEventListener("change", function () {
     if (checkbox.checked) setValid();
   });

   form.addEventListener("submit", function (event) {
     event.preventDefault();
     statusMsg.textContent = "";
     statusMsg.className = "status-message";

     if (!checkbox.checked) {
       setInvalid();
       checkbox.focus();
       return;
     }

     setValid();
     statusMsg.textContent = "You have successfully agreed to the Terms of Use.";
     statusMsg.classList.add("success");
   });
 })();

