   padding-left: 2rem;
   display: flex;
   align-items: flex-start;
   gap: 0.25rem;
 }

 .error-text[hidden] { display: none; }

 /* Error field highlight */
 .form-field:has([aria-invalid="true"]) {
   background: var(--error-bg);
   border-radius: 6px;
   padding: 0.75rem;
 }

 /* ── Required legend ───────────────────────────────────────────── */
